const body = $json?.body ?? null;
const payload = (body && typeof body === "object") ? body : $json;

// Promote webhook body fields to top-level
const merged = (body && typeof body === "object") ? { ...$json, ...body } : { ...$json };

// -------------------- question --------------------
const qRaw =
  payload?.input?.question ??
  payload?.question ??
  payload?.user_text ??               // FIX
  merged?.user_text ??                // FIX (на всякий)
  payload?.text ??
  payload?.telegram?.message?.text ??
  merged?.telegram?.message?.text ??
  "";

const question = String(qRaw).replace(/^\s*=\s*/, "").trim(); // FIX: strip leading "="

// -------------------- kb_ref --------------------
const kbRefRaw =
  payload?.meta?.kb_ref ??
  payload?.kb_ref ??
  merged?.meta?.kb_ref ??
  merged?.kb_ref ??
  null;

function normKbRef(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (!s) return null;
  const low = s.toLowerCase();
  if (low === "null" || low === "undefined") return null;
  return s;
}

let kb_ref = normKbRef(kbRefRaw);
if (!kb_ref) kb_ref = "ceo_x_demo"; // optional default for demo

// -------------------- retrieval --------------------
const retrievalIn =
  (payload?.retrieval && typeof payload.retrieval === "object") ? payload.retrieval :
  (merged?.retrieval && typeof merged.retrieval === "object") ? merged.retrieval :
  {};

const topKRaw = retrievalIn?.top_k ?? retrievalIn?.topK ?? payload?.top_k ?? payload?.topK ?? null;
const top_k_num = topKRaw == null ? 5 : Number(topKRaw);

const retrieval = {
  ...retrievalIn,
  top_k: (Number.isFinite(top_k_num) && top_k_num > 0) ? top_k_num : 5,
};

// -------------------- chat_id / user_id --------------------
const chatIdRaw =
  payload?.meta?.chat_id ??
  payload?.chat_id ??
  payload?.body?.chat_id ??
  payload?.telegram?.message?.chat?.id ??
  merged?.meta?.chat_id ??
  merged?.chat_id ??
  merged?.telegram?.message?.chat?.id ??
  null;

const userIdRaw =
  payload?.meta?.user_id ??
  payload?.user_id ??
  payload?.body?.user_id ??
  payload?.telegram?.message?.from?.id ??
  merged?.meta?.user_id ??
  merged?.user_id ??
  merged?.telegram?.message?.from?.id ??
  null;

const chat_id = chatIdRaw == null ? null : Number(chatIdRaw);
const user_id = userIdRaw == null ? null : Number(userIdRaw);

// -------------------- request_id --------------------
const request_id =
  payload?.meta?.request_id ??
  payload?.request_id ??
  merged?.meta?.request_id ??
  merged?.request_id ??
  null;

// -------------------- meta / input --------------------
const metaIn = (payload?.meta && typeof payload.meta === "object") ? payload.meta : (merged?.meta ?? {});
const inputIn = (payload?.input && typeof payload.input === "object") ? payload.input : (merged?.input ?? {});

const meta = {
  ...metaIn,
  kb_ref,
};

const input = {
  ...inputIn,
  question: (inputIn?.question ?? question),
};

return [{
  json: {
    ...merged,
    kb_ref,
    retrieval,
    meta,
    input,
    question,
    chat_id: Number.isFinite(chat_id) ? chat_id : null,
    user_id: Number.isFinite(user_id) ? user_id : null,
    request_id,
  },
}];

const idx = $itemIndex;
const env = $items("KB — Input Normalize")?.[idx]?.json ?? {};
const emb = $json.data?.[0]?.embedding;
if (!emb) throw new Error("No embedding in OpenAI response");

return {
  json: {
    ...env,
    query_embedding: emb,
    meta: {
      ...(env.meta ?? {}),
      embedding_model: $json.model ?? "text-embedding-3-small",
    },
    timers: {
      ...(env.timers ?? {}),
      t_after_embed_ms: Date.now(),
    },
  },
};

// KB — Build Context (preserve incoming fields)

// 1) текущий item уже содержит gate_mode/top_distance_num/distance_stats/retrieval_rows и т.п.
const base = items?.[0]?.json ?? {};

// 2) исходный envelope/контекст из ноды с эмбеддингом (если нужен)
const env = $node["KB — Extract Query Embedding"]?.json ?? {};

// 3) rows: предпочитаем retrieval_rows (если уже вложены), иначе собираем из items
let rows = [];
if (Array.isArray(base.retrieval_rows) && base.retrieval_rows.length) {
  rows = base.retrieval_rows.filter(r => r && r.content);
} else {
  rows = (items || []).map(i => i.json).filter(r => r && r.content);
}

// 4) сортировка по score desc
rows.sort((a, b) => (b.score ?? 0) - (a.score ?? 0));

const MAX_CHARS_PER_CHUNK = 1400;

const kb_sources = rows.map((r, idx) => ({
  n: idx + 1,
  chunk_id: r.chunk_id ?? null,
  doc: r.doc ?? null,
  section: r.section ?? null,
  source_url: r.source_url ?? null,
  score: r.score ?? null,
  distance: r.distance ?? null,
}));

const kb_context_text = rows.map((r, idx) => {
  let content = String(r.content ?? "").trim();
  if (content.length > MAX_CHARS_PER_CHUNK) content = content.slice(0, MAX_CHARS_PER_CHUNK) + "…";
  const scoreStr = Number(r.score ?? 0).toFixed(3);
  const distStr = r.distance == null ? "" : ` distance=${Number(r.distance).toFixed(3)}`;
  return `[${idx + 1}] doc="${r.doc ?? ""}" section="${r.section ?? ""}" score=${scoreStr}${distStr}\n${content}`;
}).join("\n\n");

const top_score = rows[0]?.score ?? null;
const top_distance = rows[0]?.distance ?? base.top_distance_num ?? null;

// 5) МЕРДЖ: сохраняем base поля, добавляем env поля (если их нет), потом перезаписываем retrieval/kb_*
const merged = {
  ...env,      // env как дефолты
  ...base,     // base важнее (сохранить gate_mode/top_distance_num/...)
  retrieval: {
    ...(env.retrieval ?? {}),
    ...(base.retrieval ?? {}),
    hits_count: rows.length,
    top_score,
    top_distance,
    hits: kb_sources,
    compiled_context: kb_context_text,
  },
  kb_context_text,
  kb_sources,
};

return [{ json: merged }];

return items.map(item => {
  const j = item.json;

  const picked = Array.isArray(j.output?.picked_hits) ? j.output.picked_hits : [];
  const sources = picked
    .map((h, i) => ({
      n: h.n ?? (i + 1),
      chunk_id: h.chunk_id ?? null,
      doc: h.doc ?? "",
      section: h.section ?? "",
      source_url: h.source_url ?? null,
      score: Number(h.score ?? 0)
    }))
    .sort((a, b) => b.score - a.score)
    .slice(0, 5);

  j.output = j.output ?? {};
  j.output.sources = sources;

  return { json: j };
});

return items.map(item => {
  const j = item.json;

  const mode = String(j.decision?.mode ?? "NO_ANSWER").toUpperCase();
  const answerText = (j.output?.answer_text ?? "").trim();
  const clarify = Array.isArray(j.output?.clarify) ? j.output.clarify : [];
  const sources = Array.isArray(j.output?.sources) ? j.output.sources : [];

  let text = "";

  if (mode === "ALLOW") {
    text = answerText || "OK.";

    if (sources.length) {
      const sourcesBlock =
        "\n\nSources:\n" +
        sources.map((s, i) => {
          const title = `${s.doc}${s.section ? " — " + s.section : ""}`;
          const url = s.source_url ? `\n${s.source_url}` : "";
          return `${i + 1}) ${title}${url}`;
        }).join("\n\n");

      text += sourcesBlock;
    }
  } else if (mode === "CLARIFY") {
    const qs = clarify.length ? clarify : ["Please уточни вопрос."];
    text = "I need a bit more info:\n" + qs.map(x => `- ${x}`).join("\n");
  } else {
    text = "I couldn't find the answer in the Knowledge Base.";
  }

  j.output = j.output ?? {};
  j.output.reply_text = text;
  j.output.answer = text; // backward-compat

  return { json: j };
});

return items.map(item => {
  const j = item.json;

  delete j.query_embedding;

  if (j.retrieval) {
    delete j.retrieval.compiled_context;
    if (Array.isArray(j.retrieval.hits)) {
      j.retrieval.hits = j.retrieval.hits.map(h => {
        const hh = { ...h };
        delete hh.embedding;
        delete hh.embedding_vector;
        return hh;
      });
    }
  }

  if (j.llm) {
    delete j.llm.raw_text;
  }

  if (j.output) {
    delete j.output.picked_hits;
  }

  return { json: j };
});

return items.map(item => {
  const j = item.json;

  j.decision = j.decision ?? {};
  j.output = j.output ?? {};

  const mode = String(j.decision.mode ?? "NO_ANSWER").toUpperCase();

  // Keep fallback responses citation-free (sources are attached only for ALLOW).
  j.output.sources = [];

  if (mode === "CLARIFY") {
    if (!String(j.output.answer ?? "").trim()) {
      j.output.answer =
        "I found partially relevant info in the knowledge base, but I need a bit more detail to answer.\n\n" +
        "What to clarify:\n" +
        "- Which exact section/process are you referring to (function/page/step name)?\n" +
        "- Which system/integration is this about (if there are multiple)?";
    }
  } else {
    if (!String(j.output.answer ?? "").trim()) {
      j.output.answer =
        "I couldn’t find an answer in the knowledge base for this question.\n\n" +
        "What you can do:\n" +
        "- Rephrase the question\n" +
        "- Add 1–2 details (feature/section name, error code, step in the process)";
    }
  }

  return { json: j };
});

return items.map(item => {
  const j = item.json;

  delete j.query_embedding;

  // обычно при fallback контекст/источники тоже не нужны дальше
  // (оставь, если хочешь видеть в логах)
  // delete j.kb_context_text;
  // delete j.kb_sources;

  return { json: j };
});

// KB — Parse Answer (safe, no node-name dependency)
// Expects:
// - $json contains OpenAI response object (Responses API shape) OR
// - $json has { base: <gate/context object>, openai: <response> } OR
// - $json has { ctx/base/gate: <...>, ...openaiResponseFields }
//
// Output: { ...base, decision.mode, output.answer_text/clarify/picked_hits, llm.raw_text/parsed }

function stripCodeFences(s) {
  return String(s ?? "")
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();
}

function extractResponsesOutputText(resp) {
  const out = resp?.output;
  if (Array.isArray(out)) {
    for (const item of out) {
      if (item?.type === "message" && Array.isArray(item?.content)) {
        for (const c of item.content) {
          if (c?.type === "output_text" && typeof c?.text === "string" && c.text.trim()) {
            return c.text.trim();
          }
        }
      }
    }
  }
  return "";
}

function extractChatCompletionsText(resp) {
  const cc =
    resp?.choices?.[0]?.message?.content ??
    resp?.data?.choices?.[0]?.message?.content ??
    resp?.message?.content;
  if (typeof cc === "string" && cc.trim()) return cc.trim();
  return "";
}

function extractResponseText(resp) {
  const t = extractResponsesOutputText(resp);
  if (t) return t;
  const cc = extractChatCompletionsText(resp);
  if (cc) return cc;
  if (typeof resp === "string" && resp.trim()) return resp.trim();
  return "";
}

function parseJsonLoose(raw) {
  const s = stripCodeFences(raw);
  try {
    const p = JSON.parse(s);
    if (typeof p === "string") return JSON.parse(stripCodeFences(p));
    return p;
  } catch {}
  const m = s.match(/\{[\s\S]*\}/);
  if (m) {
    try { return JSON.parse(m[0]); } catch {}
  }
  return null;
}

function normalizeMode(m) {
  const x = String(m ?? "").trim().toUpperCase();
  if (x === "ANSWER") return "ALLOW";
  if (x === "ALLOW") return "ALLOW";
  if (x === "CLARIFY") return "CLARIFY";
  if (x === "NO_ANSWER" || x === "NOANSWER" || x === "NO-ANSWER") return "NO_ANSWER";
  return "";
}

function ensureArray(x) {
  if (Array.isArray(x)) return x;
  if (typeof x === "string" && x.trim()) return [x.trim()];
  return [];
}

function extractModel(resp) {
  const direct = [resp?.model, resp?.data?.model, resp?.info?.model, resp?.metadata?.model];
  for (const m of direct) if (typeof m === "string" && m.trim()) return m.trim();
  return "";
}

function pickHits({ parsed, answerText, hits }) {
  // Minimal: keep top 1-3 hits by score, or match explicit sources if present
  const byN = new Map();
  const byId = new Map();
  hits.forEach((h, idx) => {
    byN.set(idx + 1, { ...h, n: idx + 1 });
    if (h?.chunk_id) byId.set(String(h.chunk_id), { ...h, n: idx + 1 });
  });

  const explicit = parsed?.sources;
  if (Array.isArray(explicit) && explicit.length) {
    const picked = [];
    for (const x of explicit) {
      if (typeof x === "number" || /^\d+$/.test(String(x))) {
        const h = byN.get(Number(x));
        if (h) picked.push(h);
      } else {
        const h = byId.get(String(x));
        if (h) picked.push(h);
      }
    }
    if (picked.length) return picked.slice(0, 3);
  }

  // Fallback: take best scored 1-3
  const sorted = [...hits].sort((a,b) => Number(b?.score ?? 0) - Number(a?.score ?? 0));
  return sorted.slice(0, 3);
}

// ====== main: locate base + openai response safely ======
const j = $json;

// Heuristics: base/context object is usually the one that contains retrieval/decision/kb_ref etc.
const base =
  j.base ??
  j.ctx ??
  j.context ??
  j.gate ??
  j.payload ??
  (j.retrieval || j.decision || j.kb_ref ? j : null) ??
  {};

// OpenAI response object (Responses API) might be $json itself or under openai/response/body/result
const resp =
  j.openai ??
  j.response ??
  j.body ??
  j.result ??
  (j.object === "response" && j.output ? j : null) ??
  j;

// Extract model output text + parse JSON
const raw = extractResponseText(resp);
const parsed = parseJsonLoose(raw);

// Gate mode from retrieval layer (your MUST)
const gateMode = String(base?.gate_mode ?? base?.decision?.mode ?? "ALLOW").toUpperCase();

// LLM mode (optional) — but we will NOT let it override gate unless you want
let llmMode = normalizeMode(parsed?.mode);
if (!llmMode) llmMode = "CLARIFY";

let finalMode = gateMode;
let finalReason = base?.decision?.reason ?? "ok";

let answerText = "";
let clarify = [];

// If gate is ALLOW, we use LLM answer/clarify/no_answer content
if (gateMode === "ALLOW") {
  if (llmMode === "ALLOW") {
    answerText = String(parsed?.answer ?? "").trim();
  } else if (llmMode === "CLARIFY") {
    clarify = ensureArray(parsed?.clarify);
    finalMode = "CLARIFY";
    finalReason = "llm_clarify";
  } else if (llmMode === "NO_ANSWER") {
    finalMode = "NO_ANSWER";
    finalReason = "llm_no_answer";
  }

  // Safe fallbacks
  if (finalMode === "ALLOW" && !answerText) {
    finalMode = "CLARIFY";
    finalReason = "llm_empty_answer";
    clarify = ["1) What exactly should I answer about this?", "2) Please quote the relevant line if possible."];
  }
  if (finalMode === "CLARIFY" && (!clarify || !clarify.length)) {
    clarify = ["1) What exactly should I answer about this?", "2) Please quote the relevant line if possible."];
  }
}

// Sources only for ALLOW
const hits = base?.retrieval_rows ?? base?.kb_sources ?? base?.retrieval?.hits ?? [];
const picked_hits = finalMode === "ALLOW" ? pickHits({ parsed, answerText, hits }) : [];

const detectedModel = extractModel(resp);

// Return merged object
return [{
  json: {
    ...base,
    decision: {
      ...(base.decision ?? {}),
      mode: finalMode,
      reason: finalReason,
    },
    output: {
      ...(base.output ?? {}),
      mode: finalMode,
      answer_text: finalMode === "ALLOW" ? answerText : "",
      clarify: finalMode === "CLARIFY" ? clarify : [],
      picked_hits,
    },
    llm: {
      raw_text: raw,
      parsed: parsed ?? null,
      model: detectedModel || null,
    },
  }
}];

function fnv1a32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return ("00000000" + (h >>> 0).toString(16)).slice(-8);
}

const prompt_text = ($json.body ?? $json.data ?? $json.prompt ?? "").toString();
if (!prompt_text.trim()) {
  throw new Error("PROMPT_LOAD_ERROR: empty prompt_text");
}

return [{
  json: {
    ...$json,
    prompt_text,
    meta: {
      ...( $json.meta || {} ),
      prompt_version: "v1",
      prompt_hash: "fnv1a32:" + fnv1a32(prompt_text),
    }
  }
}];

const secret = $vars.ANSWER_WEBHOOK_SECRET;

// accept both header variants
const got =
  $json?.headers?.["x-webhook-secret"] ??
  $json?.headers?.["X-Webhook-Secret"] ??
  $json?.headers?.["x-webhook-secret".toLowerCase()] ??
  $json?.headers?.["x-webhook-secret"];

if (!secret) {
  throw new Error("Server misconfig: ANSWER_WEBHOOK_SECRET is not set");
}

if (got !== secret) {
  return [{
    json: {
      ok: false,
      status: "UNAUTHORIZED",
      message: "Invalid webhook secret",
    }
  }];
}

return [{
  json: {
    ...$json,
    ok: true,
  }
}];

// Convert embedding array -> pgvector text "[...]" for safe SQL cast to vector
const j = $json ?? {};

const emb =
  j.query_embedding ??
  j.queryEmbedding ??
  j.embedding ??
  j.embeddings ??
  null;

if (!Array.isArray(emb) || emb.length === 0) {
  return [{
    json: {
      ...j,
      query_embedding_vec: null,
      _err: "no_query_embedding_array",
    }
  }];
}

// ensure numbers, avoid "null"/"NaN"
const nums = emb.map(x => Number(x)).filter(x => Number.isFinite(x));

if (nums.length === 0) {
  return [{
    json: {
      ...j,
      query_embedding_vec: null,
      _err: "embedding_not_numeric",
    }
  }];
}

// pgvector accepts text like: [0.1,0.2,...]
const query_embedding_vec = `[${nums.join(",")}]`;

return [{
  json: {
    ...j,
    query_embedding_vec,
    query_embedding_dim: nums.length,
  }
}];

const rows = $input.all().map(i => i.json);

const ds = rows.map(r => Number(r.distance)).filter(Number.isFinite);
const min_distance = ds.length ? Math.min(...ds) : null;
const max_distance = ds.length ? Math.max(...ds) : null;
const avg_distance = ds.length ? ds.reduce((a,b)=>a+b,0)/ds.length : null;

const best = rows
  .map(r => ({ ...r, _d: Number(r.distance) }))
  .filter(r => Number.isFinite(r._d))
  .sort((a,b)=>a._d-b._d)[0] ?? null;

const top_distance = best ? Number(best.distance) : null;

// DEMO thresholds (cosine distance)
const T_ALLOW = 0.78;
const T_NO = 0.82;

let gate_mode = "NO_ANSWER";
if (top_distance !== null) {
  if (top_distance <= T_ALLOW) gate_mode = "ALLOW";
  else if (top_distance <= T_NO) gate_mode = "CLARIFY";
}

return [{
  json: {
    ...(best ?? {}),
    retrieval_rows: rows,
    retrieved_count: rows.length,

    top_distance_num: top_distance,
    gate_mode,
    gate_threshold_allow: T_ALLOW,
    gate_threshold_no: T_NO,

    distance_stats: { min: min_distance, avg: avg_distance, max: max_distance, n: ds.length },
  }
}];

const items = $input.all();

if (!items.length) {
  return [{
    json: {
      gate_mode: "CLARIFY",
      reply_text:
        "I found related fragments, but there's not enough context to answer.\n" +
        "1) What exactly is it about (name/ticker/link)?\n" +
        "2) What output do you want: a fact, a risk assessment, or a 2–3 bullet summary?"
    }
  }];
}

for (const item of items) {
  const j = item.json;

  const q = String(j.user_text ?? j.query ?? j.text ?? "").trim();

  const q1 = "What exactly is it about (name/ticker/link)?";
  const q2 = "What output do you want: a fact, a risk assessment, or a 2–3 bullet summary?";

  // deterministic: 1–2 questions max
  const questions = (q.length < 25) ? [q1, q2] : [q2];

  j.gate_mode = j.gate_mode ?? "CLARIFY";
  j.reply_text =
    "I found related fragments, but there's not enough context to answer.\n" +
    questions.slice(0, 2).map((x, i) => `${i + 1}) ${x}`).join("\n");
}

return items;

const items = $input.all();

if (!items.length) {
  return [{
    json: {
      gate_mode: "NO_ANSWER",
      reply_text:
        "I can't answer from the knowledge base: I couldn't find sufficiently close sources.\n" +
        "Please send: (1) the exact name/ticker/link and what you want to know, or (2) a short quote/text snippet."
    }
  }];
}

for (const item of items) {
  item.json.gate_mode = item.json.gate_mode ?? "NO_ANSWER";
  item.json.reply_text =
    "I can't answer from the knowledge base: I couldn't find sufficiently close sources.\n" +
    "Please send: (1) the exact name/ticker/link and what you want to know, or (2) a short quote/text snippet.";
}

return items;

const j = (items?.[0]?.json) ?? $json ?? {};

// 1) mode: СНАЧАЛА gate_mode
const mode =
  j?.gate_mode ??
  j?.decision?.mode ??
  j?.output?.mode ??
  j?.mode ??
  null;

// 2) reply_text:
// - если gate_mode=ALLOW -> бери ответ LLM (если есть), иначе fallback на уже собранный reply_text
const llm_reply =
  j?.output?.reply_text ??
  j?.output?.answer ??
  j?.reply_text ??
  j?.answer_text ??
  "";

const reply_text = (mode === "ALLOW")
  ? (llm_reply || j?.reply_text || "")
  : (j?.reply_text || llm_reply || "");

// 3) sources: если ALLOW — обязательно 1–3 из retrieval_rows/kb_sources
let sources =
  j?.output?.sources ??
  j?.output?.picked_hits ??
  j?.picked_hits ??
  j?.sources ??
  j?.citations ??
  [];

const fallback =
  j?.kb_sources ??
  j?.retrieval_rows ??
  j?.retrieval?.hits ??
  [];

if (mode === "ALLOW" && (!Array.isArray(sources) || sources.length === 0)) {
  sources = Array.isArray(fallback) ? fallback.slice(0, 3) : [];
} else if (mode !== "ALLOW") {
  sources = [];
}

// normalize source_url/url
sources = (Array.isArray(sources) ? sources : []).map((s, idx) => ({
  n: s?.n ?? (idx + 1),
  chunk_id: s?.chunk_id,
  doc: s?.doc,
  section: s?.section,
  source_url: s?.source_url ?? s?.url,
  score: s?.score,
  distance: s?.distance,
}));

// stats
const top_distance_num =
  (typeof j?.top_distance_num === "number" ? j.top_distance_num : null) ??
  (typeof j?.retrieval?.top_distance_num === "number" ? j.retrieval.top_distance_num : null) ??
  null;

const distance_stats =
  (j?.distance_stats && typeof j.distance_stats === "object") ? j.distance_stats :
