const j = $json;

// где лежит вопрос
const userQ =
  j?.user_text ??
  j?.test_case?.query ??
  j?.query ??
  "";

// где лежит контекст (как ты его называешь в Build Context)
const kbCtx =
  j?.kb_context_text ??
  j?.kb_context ??
  j?.context_text ??
  "";

// prompt (после Prompt — Load)
const prompt =
  j?.prompt_text ??
  j?.data ??      // если Prompt Load кладет в data
  "";

const llm_input =
`${prompt}

## KB CONTEXT
${kbCtx}

## USER QUESTION
${userQ}
`;

return [{
  json: {
    ...j,
    llm_input,
    _debug_llm: {
      has_prompt: !!prompt,
      has_kb_context: !!kbCtx,
      has_user_q: !!userQ,
      user_q_preview: String(userQ).slice(0, 120),
    }
  }
}];
